if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$act=$_POST['action']??'';$oid=(int)$_POST['order_id'];$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM pesanan WHERE id=? AND pekerja_id=? FOR UPDATE');$q->execute([$oid,$u['id']]);$o=$q->fetch();if(!$o)throw new RuntimeException('Pesanan tidak ditemukan.');if($act==='quote'&&$o['status']==='Menunggu'){$price=(float)$_POST['harga'];$days=(int)$_POST['hari'];$revs=(int)$_POST['revisi'];$desc=trim($_POST['deskripsi']??'');if($price<=0||$days<1||$days>365||$revs<0||$revs>50||$desc==='')throw new RuntimeException('Isi penawaran dengan benar.');$pdo->prepare("UPDATE penawaran SET status='Digantikan' WHERE pesanan_id=? AND status='Menunggu'")->execute([$oid]);$q=$pdo->prepare("INSERT INTO penawaran (pesanan_id,dibuat_oleh,harga,estimasi_hari,jumlah_revisi,deskripsi_pekerjaan,berlaku_sampai,status) VALUES (?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 72 HOUR),'Menunggu')");$q->execute([$oid,$u['id'],$price,$days,$revs,$desc]);$qid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO penawaran_riwayat (penawaran_id,versi,diubah_oleh,harga,estimasi_hari,jumlah_revisi,deskripsi_pekerjaan,status) VALUES (?,1,?,?,?,?,?,\'Diajukan\')')->execute([$qid,$u['id'],$price,$days,$revs,$desc]);notify($pdo,(int)$o['pembeli_id'],'pesanan','Penawaran harga baru','Pekerja mengirim penawaran untuk '.$o['nama_jasa'],'/penyedia/tahap4-pesanan.php?id='.$oid);t4_audit($pdo,(int)$u['id'],'quote.created','penawaran',$qid);$pdo->commit();t4_flash_redirect('Penawaran berhasil dikirim.','/pekerja/tahap4-pesanan.php?id='.$oid);}if($act==='start'){if($o['status_pembayaran']!=='Berhasil'||$o['status_pekerjaan']!=='Siap Dikerjakan')throw new RuntimeException('Pekerjaan baru dapat dimulai setelah pembayaran terverifikasi.');$pdo->prepare("UPDATE pesanan SET status='Dikerjakan',status_pekerjaan='Dikerjakan',started_at=NOW() WHERE id=?")->execute([$oid]);$pdo->prepare("INSERT INTO riwayat_pesanan (pesanan_id,status_sebelumnya,status_terbaru,catatan,diubah_oleh) VALUES (?,?,'Dikerjakan','Pekerjaan dimulai setelah pembayaran diverifikasi',?)")->execute([$oid,$o['status'],$u['id']]);}elseif($act==='deliver'&&in_array($o['status_pekerjaan'],['Dikerjakan','Revisi'],true)){$note=trim($_POST['catatan']??'');$link=trim($_POST['tautan']??'');if($note===''||mb_strlen($note)>3000||($link!==''&&!filter_var($link,FILTER_VALIDATE_URL)))throw new RuntimeException('Catatan wajib diisi dan tautan harus URL valid.');$q=$pdo->prepare('SELECT COALESCE(MAX(versi),0)+1 FROM pengiriman_hasil WHERE pesanan_id=?');$q->execute([$oid]);$v=(int)$q->fetchColumn();$pdo->prepare("INSERT INTO pengiriman_hasil (pesanan_id,versi,catatan,tautan_hasil,dikirim_oleh) VALUES (?,?,?,?,?)")->execute([$oid,$v,$note,$link?:null,$u['id']]);$pdo->prepare("UPDATE pesanan SET status_pekerjaan='Menunggu Review',submitted_at=NOW() WHERE id=?")->execute([$oid]);$pdo->prepare("UPDATE permintaan_revisi SET status='Dikirim Ulang',selesai_at=NOW() WHERE pesanan_id=? AND status IN ('Diminta','Dikerjakan')")->execute([$oid]);notify($pdo,(int)$o['pembeli_id'],'pesanan','Hasil pekerjaan dikirim','Pekerja telah mengirim hasil pesanan '.$o['kode_pesanan'],'/penyedia/tahap4-pesanan.php?id='.$oid);}else throw new RuntimeException('Aksi tidak diizinkan atau status pesanan tidak sesuai.');t4_audit($pdo,(int)$u['id'],'order.'.$act,'pesanan',$oid);$pdo->commit();t4_flash_redirect('Perubahan pesanan tersimpan.','/pekerja/tahap4-pesanan.php?id='.$oid);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e instanceof RuntimeException?$e->getMessage():'Aksi gagal.';error_log('t4 worker order: '.$e->getMessage());}}
$oid=(int)($_GET['id']??0);$params=[$u['id']];$sql='SELECT o.*,b.nama nama_pembeli FROM pesanan o JOIN users b ON b.id=o.pembeli_id WHERE o.pekerja_id=?';if($oid){$sql.=' AND o.id=?';$params[]=$oid;}$sql.=' ORDER BY o.created_at DESC LIMIT 80';$q=$pdo->prepare($sql);$q->execute($params);$orders=$q->fetchAll();$sel=$orders[0]??null;if($sel){$q=$pdo->prepare('SELECT * FROM penawaran WHERE pesanan_id=? ORDER BY created_at DESC');$q->execute([$sel['id']]);$quotes=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM pengiriman_hasil WHERE pesanan_id=? ORDER BY versi DESC');$q->execute([$sel['id']]);$deliveries=$q->fetchAll();}$pageTitle='Pesanan masuk';require __DIR__.'/../includes/header.php';?>
